<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
if (user_role() !== 'kepala_sekolah') { deny_access(); }
require_once __DIR__ . '/../includes/school_profile.php';
$profil=school_profile($pdo);$today=date('Y-m-d');
function kt_rows(PDO $pdo,string $sql,array $p=[]):array{try{$st=$pdo->prepare($sql);$st->execute($p);return $st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable){return [];}}
$items=[];
foreach(kt_rows($pdo,"SELECT 'BK' sumber,s.nama,cb.tanggal,cb.tindak_lanjut detail,cb.status FROM catatan_bk cb JOIN siswa s ON s.id=cb.siswa_id WHERE cb.status IN ('baru','proses') OR (cb.tindak_lanjut IS NOT NULL AND cb.tindak_lanjut<>'' AND cb.status<>'selesai') ORDER BY cb.tanggal DESC LIMIT 20") as $r){$items[]=$r;}
foreach(kt_rows($pdo,"SELECT 'Pembinaan' sumber,s.nama,ps.tanggal,ps.tindak_lanjut detail,ps.status FROM pembinaan_siswa ps JOIN siswa s ON s.id=ps.siswa_id WHERE ps.status IN ('direncanakan','proses') ORDER BY ps.tanggal DESC LIMIT 20") as $r){$items[]=$r;}
foreach(kt_rows($pdo,"SELECT 'Home Visit' sumber,s.nama,hv.tanggal_rencana tanggal,hv.tindak_lanjut detail,hv.status FROM home_visit hv JOIN siswa s ON s.id=hv.siswa_id WHERE hv.status='direncanakan' OR (hv.tindak_lanjut IS NOT NULL AND hv.tindak_lanjut<>'' AND hv.status<>'dilaksanakan') ORDER BY hv.tanggal_rencana ASC LIMIT 20") as $r){$items[]=$r;}
foreach(kt_rows($pdo,"SELECT 'UKS Rujukan' sumber,s.nama,ur.tanggal,ur.hasil_tindak_lanjut detail,ur.status FROM uks_rujukan ur JOIN siswa s ON s.id=ur.siswa_id WHERE ur.status IN ('direncanakan','dirujuk') ORDER BY ur.tanggal DESC LIMIT 20") as $r){$items[]=$r;}
usort($items,fn($a,$b)=>strcmp((string)($a['tanggal']??''),(string)($b['tanggal']??'')));
$page_title='Tindak Lanjut';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div><h1>Tindak Lanjut</h1><div class="topbar-subtitle"><?=e($profil['nama_sekolah'])?></div></div><div class="topbar-user"><strong><?=e(user_name())?></strong><span>Kepala Sekolah</span></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-list-check"></i> Tindak Lanjut</h1><p>Daftar hal yang masih membutuhkan perhatian berdasarkan data layanan sekolah.</p></div></div><div class="dashboard-table"><table><thead><tr><th>Sumber</th><th>Siswa</th><th>Tanggal</th><th>Tindak Lanjut</th><th>Status</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="5" class="empty-state">Tidak ada tindak lanjut yang perlu diperhatikan saat ini.</td></tr><?php else:foreach($items as $r):?><tr><td><strong><?=e((string)$r['sumber'])?></strong></td><td><?=e((string)$r['nama'])?></td><td><?=!empty($r['tanggal'])?e(date('d-m-Y',strtotime((string)$r['tanggal']))):'-'?></td><td><?=e((string)($r['detail']??'-'))?></td><td><span class="status-pill <?=in_array((string)$r['status'],['selesai','dilaksanakan'],true)?'on':'off'?>"><?=e((string)$r['status'])?></span></td></tr><?php endforeach;endif;?></tbody></table></div><div class="dashboard-note note-role" style="margin-top:18px"><i class="bi bi-eye-fill"></i><div><strong>Read Only</strong>Kepala Sekolah menerima informasi tindak lanjut. Perubahan status atau catatan dilakukan oleh petugas yang berwenang.</div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php'; ?>
